/// File-backed attached-session transport: [SessionEventSource] tails
/// the session JSONL through the [ExecutionEnv] filesystem; the input
/// channel rides the agent messaging fabric ([AgentMessageKind.user] to
/// the session's `main` mailbox). Works for any two Fa processes sharing
/// the sessions root (the macOS App Group) — the CLI owns the JSONL, the
/// app only reads it and hands input over.
library;

// ignore_for_file: prefer_initializing_formals

import 'dart:async';
import 'dart:convert';

import '../../context.dart';
import '../../env/execution_env.dart';
import '../../messaging/agent_message.dart';
import '../../messaging/file_messaging_repository.dart';
import '../../types.dart';
import '../session_record.dart';
import 'session_attachment.dart';

final class FileSessionEventSource implements SessionEventSource {
  /// Creates the source. [resolvePath] maps a session id to its JSONL
  /// path (the host resolves it however it likes — typically
  /// `JsonlSessionRepo.list` metadata); [pollInterval] is injectable for
  /// tests.
  FileSessionEventSource({
    required ExecutionEnv env,
    required Future<String?> Function(String sessionId) resolvePath,
    Duration pollInterval = const Duration(seconds: 1),
  }) : _env = env,
       _resolvePath = resolvePath,
       _pollInterval = pollInterval;

  final ExecutionEnv _env;
  final Future<String?> Function(String sessionId) _resolvePath;
  final Duration _pollInterval;

  final _controllers = <String, StreamController<AttachedSessionEvent>>{};
  final _watchers = <String, Future<void>>{};
  final _deliveredLines = <String, int>{};
  final _disposed = false;

  @override
  Stream<AttachedSessionEvent> watch(String sessionId) {
    final existing = _controllers[sessionId];
    if (existing != null) return existing.stream;
    final controller = StreamController<AttachedSessionEvent>();
    _controllers[sessionId] = controller;
    _watchers[sessionId] = _runWatcher(sessionId, controller);
    return controller.stream;
  }

  Future<void> _runWatcher(
    String sessionId,
    StreamController<AttachedSessionEvent> controller,
  ) async {
    // First poll establishes the baseline and emits the backlog; every
    // later poll emits only what grew. A missing file is not an error —
    // the owning process creates the JSONL lazily.
    while (!controller.isClosed && !_disposed) {
      final path = await _resolvePath(sessionId);
      final lines = path == null
          ? null
          : (await _env.readTextLines(path)).valueOrNull;
      final total = lines?.length ?? 0;
      final start = _deliveredLines[sessionId];
      if (start == null) {
        _deliveredLines[sessionId] = total;
        if (lines != null) await _emit(sessionId, controller, lines, 0);
      } else if (total > start) {
        _deliveredLines[sessionId] = total;
        await _emit(sessionId, controller, lines ?? const [], start);
      }
      await Future<void>.delayed(_pollInterval);
    }
  }

  Future<void> _emit(
    String sessionId,
    StreamController<AttachedSessionEvent> controller,
    List<String> lines,
    int start,
  ) async {
    final appended = <AttachedMessage>[];
    for (final line in lines.skip(start)) {
      final row = _rowFromLine(line);
      if (row != null) appended.add(row);
    }
    if (appended.isEmpty || controller.isClosed) return;
    controller.add(AttachedSessionEvent(appended: appended));
  }

  /// One JSONL line → render row; null for records the view skips
  /// (headers, compaction markers, tool results …).
  AttachedMessage? _rowFromLine(String line) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) return null;
    final Map<String, dynamic> json;
    try {
      final decoded = jsonDecode(trimmed);
      if (decoded is! Map<String, dynamic>) return null;
      json = decoded;
    } on Object {
      return null; // torn write — the next poll re-reads cleanly
    }
    if (json['type'] != 'message') return null;
    final MessageRecord record;
    try {
      final parsed = SessionRecord.fromJson(json);
      if (parsed is! MessageRecord) return null;
      record = parsed;
    } on Object {
      return null;
    }
    return attachedRowFromMessage(record.message);
  }

  @override
  Future<void> dispose() async {
    for (final controller in _controllers.values) {
      if (!controller.isClosed) await controller.close();
    }
    _controllers.clear();
    _watchers.clear();
    _deliveredLines.clear();
  }
}

/// Renders one conversation [Message] as an attached-view row, or null
/// for content the view skips (tool results, empty rows).
AttachedMessage? attachedRowFromMessage(Message message) {
  switch (message) {
    case UserMessage():
      final text = _textOf(message.content);
      if (text == null) return null; // tool results arrive as user rows
      return AttachedMessage(role: AttachedMessageRole.user, text: text);
    case AssistantMessage():
      final text = _textOf(message.content);
      if (text != null && text.isNotEmpty) {
        return AttachedMessage(role: AttachedMessageRole.assistant, text: text);
      }
      final toolName = _toolNameOf(message.content);
      if (toolName != null) {
        return AttachedMessage(
          role: AttachedMessageRole.tool,
          text: '',
          toolName: toolName,
        );
      }
      return null;
    default:
      return null;
  }
}

String? _textOf(Object content) {
  switch (content) {
    case String():
      return content.isEmpty ? null : content;
    case List():
      final buf = StringBuffer();
      for (final block in content) {
        if (block is TextContent) buf.write(block.text);
      }
      final joined = buf.toString();
      return joined.isEmpty ? null : joined;
    default:
      return null;
  }
}

String? _toolNameOf(Object content) {
  if (content is! List) return null;
  for (final block in content) {
    if (block is ToolCall && block.name.isNotEmpty) return block.name;
  }
  return null;
}

/// Hands user input to the session's owning process through the agent
/// messaging fabric: an [AgentMessageKind.user] envelope addressed to the
/// session's `main` mailbox. The CLI's inbox watcher wakes and delivers
/// it as a user turn.
final class FileSessionInputChannel implements SessionInputChannel {
  /// Creates the channel over the fabric at [messagingRoot]. [fromId] is
  /// the attribution the owner's transcript renders (`[from $fromId] …`)
  /// — the app sends as `Fa.app user`, a viewer CLI as `fa CLI user`.
  FileSessionInputChannel({
    required FileMessagingRepository repository,
    this.fromId = 'Fa.app user',
  }) : _repository = repository;

  final FileMessagingRepository _repository;

  /// The sender attribution carried on every sent envelope.
  final String fromId;

  @override
  Future<void> send(String sessionId, String text) async {
    // Absolute cross-instance address: `<sessionId>/main`.
    await _repository.send(
      AgentMessage(
        id: newMessageId(),
        fromId: fromId,
        toId: '$sessionId/main',
        text: text,
        sentAt: DateTime.now().toUtc().toIso8601String(),
        kind: AgentMessageKind.user,
      ),
    );
  }
}

Future<FlutterManagedSession> createOrResumeSession({
  required AgentConfig config,
  required Future<AgentService> Function() createFactory,
  required FutureOr<AgentService> Function() openFactory,
}) async {
  // The last ACTIVE session wins over the newest file: the user may have
  // switched back to an older chat (or a fresh empty session may have been
  // minted after it) — reopen the conversation they actually left.
  final lastActiveId = await _readLastActiveId();
  // Cache the session list once — findReusableSession also needs it,
  // and a redundant _repo.list() scans all session directories.
  List<SessionMetadata>? cachedList;
  if (lastActiveId != null) {
    try {
      cachedList = await _repo.list();
      final metadata = cachedList
          .where((m) => m.id == lastActiveId)
          .firstOrNull;
      if (metadata != null) {
        debugPrint(
          '[fah][sessions] boot: resuming last active '
          '$lastActiveId (${cachedList.length} persisted)',
        );
        return await openSession(
          metadata,
          config: config,
          serviceFactory: openFactory,
        );
      }
      debugPrint(
        '[fah][sessions] boot: last active $lastActiveId is gone '
        '(${cachedList.length} persisted) — picking reusable',
      );
    } on Object catch (error) {
      // Unreadable list/load — fall through to the reusable pick.
      debugPrint(
        '[fah][sessions] boot: last active $lastActiveId failed to '
        'list/load ($error) — picking reusable',
      );
    }
  } else {
    debugPrint(
      '[fah][sessions] boot: no last-active marker — picking reusable',
    );
  }
  final reusable = await findReusableSession(cachedSessionList: cachedList);
  if (reusable != null) {
    if (_tooLarge(reusable)) {
      debugPrint(
        '[fah][sessions] boot: reusable pick ${reusable.id} is '
        '${reusable.sizeBytes} bytes — over the load budget, creating '
        'a fresh session',
      );
    } else {
      debugPrint(
        '[fah][sessions] boot: reusable pick ${reusable.id} '
        '(created ${reusable.createdAt.toLocal()})',
      );
      try {
        return await openSession(
          reusable,
          config: config,
          serviceFactory: openFactory,
        );
      } on Object catch (error) {
        // The session failed to load (corrupt file, storage error) — fall
        // through to a fresh session rather than blocking the boot.
        debugPrint(
          '[fah][sessions] boot: reusable pick ${reusable.id} failed to '
          'load ($error) — creating a fresh session',
        );

      return session.service;
    }
  }
  return null;
}

/// The clone config: the active session's resolved config when it has
/// one, else a blank one for the same provider/model.
AgentConfig _cloneConfig(AgentService active) =>
    active.configForClone ??
    AgentConfig(
      providerKind: active.providerKind,
      modelId: active.modelId,
      baseUrl: '',
      apiKey: '',
    );

/// Opens the bound session from disk. A failure here is NOT first contact
/// — the binding is real — so it must never route into a re-mint
/// (issue #864).
Future<(AgentService?, _AppBindingResolution)> _openBoundSession(
  FlutterSessionManager manager,
  AgentService active,
  String appId,
  String boundId,
) async {
  try {
    for (final metadata in await active.listSessions()) {
      if (metadata.id == boundId) {
        final managed = await manager.openSession(
          metadata,
          config: _cloneConfig(active),
          serviceFactory: () => active.clone(),
        );
        return (managed.service, _AppBindingResolution.bound);
      }
    }
  } on Object catch (error) {
    AppLog.i('apps', 'bound session unopenable for $appId: $error');
    return (null, _AppBindingResolution.unopenable);
  }
  return (null, await _staleBindingResolution(active, appId));
}

/// The store answered without the bound id: a STALE binding (session
/// deleted) — rewriting it on the mint heals (issue #864 E4). BUT
/// `listSessions` swallows store failures into an empty list, so
/// "absent" must be verified before minting over a REAL binding: a
/// sessions root that cannot even be listed (a file in its place,
/// permission, IO) means the store is broken — the bound session may
/// still be recoverable, and minting here would rewrite the binding on
/// EVERY cold open (the surviving member of the owner's per-open mint
/// family, issue #1175). Keep the binding; run on the active session.
Future<_AppBindingResolution> _staleBindingResolution(
  AgentService active,
  String appId,
) async {
  final probe = await active.env.listDir(active.sessionsRoot);
  if (probe.isErr && probe.errorOrNull!.code != FileErrorCode.notFound) {
    AppLog.i(
      'apps',
      'sessions store unlistable for $appId '
          '(${probe.errorOrNull!.code.name}) — keeping binding',
    );
    return _AppBindingResolution.unopenable;
  }
  // notFound = a healthy store with nothing in it: the bound session is
  // truly gone — one heal-mint rewrites the binding (issue #864 E4).
  return _AppBindingResolution.firstContact;
}

